 if(f.design.computer==="brawler")offense*=1.1;if(f.design.computer==="artillery")range*=1.2;if(f.design.computer==="picket")defense*=1.08;if(f.design.computer==="carrier"&&f.ships.carrier>0)offense*=1.12;if(f.design.computer==="evasive")evasion*=1.15;
