const leaderRoll=()=>Math.max(15,Math.min(95,Math.round(50+(Math.random()+Math.random()+Math.random()-1.5)*45)));
const leaderSkill=():LeaderSkill=>({competence:leaderRoll(),judgment:leaderRoll(),ambition:leaderRoll(),loyalty:leaderRoll(),nerve:leaderRoll(),adaptability:leaderRoll(),integrity:leaderRoll()});
