const leaderExecution=(l?:Leader)=>{if(!l)return 1;const s=l.skill;if(!s)return 1;return Math.max(.62,Math.min(1.35,.62+s.competence*.004+s.judgment*.002+s.adaptability*.001+l.level*.025))};
