const leaderDescriptor=(l:Leader)=>{const s=l.skill,known=leaderKnown(l);if(!s)return "Unproven";if(known<2)return (l.reputation??50)>65?"Promising":"Unproven";const avg=(s.competence+s.judgment+s.adaptability)/3;return avg>78?"Exceptional":avg>62?"Capable":avg>45?"Mixed":avg>30?"Questionable":"Incompetent"};
