const sensorSystems=(g:Game,viewer:number)=>{const e=g.empires[viewer],seen=new Set<number>(e.systems),range=sensorRange(e);let frontier=[...new Set([...e.systems,...g.fleets.filter(f=>f.owner===viewer).map(f=>f.system)])];for(const id of frontier)seen.add(id);for(let d=0;d<range;d++){const next:number[]=[];for(const id of frontier)for(const nb of g.stars[id]?.neighbors??[])if(!seen.has(nb)){seen.add(nb);next.push(nb)}frontier=next}return seen};const intelVisible=(g:Game,viewer:number,target:number)=>{const f=g.fleets.find(x=>x.id===target);return !!f&&(f.owner===viewer||sensorSystems(g,viewer).has(f.system))};
