const treatyCost=(t:Treaty)=>t==="defense-pact"?12:t==="research-pact"?8:t==="commercial-pact"?6:4;
const treatyMin=(t:Treaty)=>t==="defense-pact"?45:t==="research-pact"?25:t==="commercial-pact"?15:t==="non-aggression"?10:0;
const warSide=(w:War,id:number)=>[w.a,...(w.attackers??[])].includes(id)?"a":[w.b,...(w.defenders??[])].includes(id)?"b":null;const warBetween=(g:Game,a:number,b:number)=>g.wars.find(w=>{const sa=warSide(w,a),sb=warSide(w,b);return sa!==null&&sb!==null&&sa!==sb});const atWar=(g:Game,a:number,b:number)=>!!warBetween(g,a,b);
