const opinion=(r:Relation,turn:number)=>r.score+r.memories.filter(m=>m.expires>turn).reduce((a,m)=>a+m.value,0);
const diplomaticValue=(g:Game,a:number,b:number,t:Treaty)=>{const r=rel(g.empires[a],b),mutual=[...Object.keys(g.empires[a].relations).map(Number)].filter(x=>x!==b&&rel(g.empires[a],x).status==="rival"&&rel(g.empires[b],x).status==="rival").length,intel=intelLevel(g,a,b);const econ=t==="commercial-pact"?(intel>=50?Math.min(30,g.empires[b].trade/4):Math.min(12,r.trust/5)):t==="research-pact"?(intel>=50?Math.min(25,g.empires[b].tech*2):Math.min(10,r.respect/6)):0;return opinion(r,g.turn)+r.trust*.7+r.reliability*.25-r.threat*.45+mutual*12+econ};
const updatePosture=(r:Relation,relativePower:number)=>{const v=r.score+r.trust-r.threat*.8;if(r.status==="rival")r.posture="competitive";else if(v>75)r.posture="friendly";else if(v>35)r.posture="cooperative";else if(v<-60)r.posture=relativePower>1.15?"hostile":"defensive";else if(v<-20)r.posture="competitive";else r.posture=relativePower>1.35?"opportunistic":"cautious"};
