const empirePower=(g:Game,id:number)=>g.fleets.filter(f=>f.owner===id).reduce((a,f)=>a+militaryPower(f,g.empires[id],undefined,g),0);const observedEmpirePower=(g:Game,a:number,b:number)=>{if(a===b)return empirePower(g,b);const intel=intelLevel(g,a,b),actual=empirePower(g,b);if(intel>=90)return actual;if(intel>=70)return Math.max(1,Math.round(actual/10)*10);if(intel>=35)return Math.max(1,Math.round(actual/50)*50);const seen=g.stars.filter(s=>known(s,a)&&s.owner===b).length;return Math.max(1,rel(g.empires[a],b).threat*4+seen*8)};
