const activeCrises=(g:Game,e:number)=>g.crises?.filter(c=>c.empire===e&&!c.resolved)??[];
const crisisLoad=(g:Game,e:number,k?:CrisisKind)=>activeCrises(g,e).filter(c=>!k||c.kind===k).reduce((a,c)=>a+c.severity,0);
const spawnCrisis=(g:Game,e:Empire,kind:CrisisKind,severity:number,planet:number|null=null,leader:number|null=null)=>{g.crises??=[];g.nextCrisis??=1;if(g.crises.some(c=>!c.resolved&&c.empire===e.id&&c.kind===kind&&(planet===null||c.planet===planet)))return;g.crises.push({id:g.nextCrisis++,empire:e.id,kind,severity:Math.min(100,severity),planet,leader,started:g.turn,duration:0,resolved:false});if(e.id===0)g.log.unshift(kind[0].toUpperCase()+kind.slice(1)+" crisis has emerged"+(planet!==null?" on "+g.planets.find(p=>p.id===planet)?.name:"")+".")};
const politicalPower=(l:Leader)=>{const s=ensureLeader(l).skill!;return l.level*8+(l.reputation??50)*.35+s.ambition*.35+s.loyalty*.15};
const network=(g:Game,a:number,b:number)=>g.intel?.find(n=>n.owner===a&&n.target===b);
const intelLevel=(g:Game,a:number,b:number)=>a===b?100:Math.round(network(g,a,b)?.intel??0);
