const counterIntel=(g:Game,e:number)=>{const empire=g.empires[e],leaders=g.leaders.filter(l=>l.owner===e),best=leaders.length?Math.max(...leaders.map(l=>{const s=l.skill;return s?(s.judgment+s.integrity+s.competence)/3:45})):45,tech=Math.min(18,empire.tech*2),policy=empire.policy==="military"?5:empire.policy==="science"?3:0;return 20+best*.35+tech+policy+(empire.ethic==="order"?8:0)};
