const intelReport=(g:Game,n:IntelNetwork)=>{const t=g.empires[n.target],p=t.pressure??strategicPressure(g,t),bits:string[]=[];if(n.intel>=20)bits.push("government "+t.government,"policy "+t.policy);if(n.intel>=35)bits.push("fleet power ~"+Math.round(empirePower(g,t.id)/10)*10,"systems "+t.systems.length);if(n.intel>=50)bits.push("credits ~"+Math.round(t.credits/25)*25,"alloys ~"+Math.round(t.alloys/25)*25);if(n.intel>=65)bits.push("internal pressure "+Math.round(p.internal),"economic pressure "+Math.round(p.economic));if(n.intel>=80)bits.push("strategic focus "+(t.strategicFocus??strategicFocus(p)),"active crises "+activeCrises(g,t.id).length);return bits.join(" · ")||"Network has not produced actionable intelligence yet."};
