const link=(stars:Star[],a:number,b:number)=>{if(a===b)return;if(!stars[a].neighbors.includes(b))stars[a].neighbors.push(b);if(!stars[b].neighbors.includes(a))stars[b].neighbors.push(a)};
const buildHyperlanes=(stars:Star[],density:GalaxyDensity)=>{const target=density==="sparse"?2:density==="dense"?4:3;for(const s of stars){const near=stars.filter(x=>x.id!==s.id).map(x=>({id:x.id,d:Math.hypot(x.x-s.x,x.y-s.y),a:Math.atan2(x.y-s.y,x.x-s.x)})).sort((a,b)=>a.d-b.d).slice(0,12);const picked:{id:number;d:number;a:number}[]=[];for(const n of near){const separated=picked.every(p=>Math.abs(Math.atan2(Math.sin(n.a-p.a),Math.cos(n.a-p.a)))>.55);if(separated||picked.length===0)picked.push(n);if(picked.length>=target)break}for(const n of picked)link(stars,s.id,n.id)}
 const components=()=>{const unseen=new Set(stars.map(s=>s.id)),out:number[][]=[];while(unseen.size){const root=unseen.values().next().value as number,q=[root],part:number[]=[];unseen.delete(root);while(q.length){const x=q.shift()!;part.push(x);for(const n of stars[x].neighbors)if(unseen.delete(n))q.push(n)}out.push(part)}return out};
 let parts=components();while(parts.length>1){const a=parts[0],b=parts.slice(1).flat();let ba=a[0],bb=b[0],best=Infinity;for(const x of a)for(const y of b){const d=Math.hypot(stars[x].x-stars[y].x,stars[x].y-stars[y].y);if(d<best){best=d;ba=x;bb=y}}link(stars,ba,bb);parts=components()}
 if(density==="dense")for(let k=0;k<Math.floor(stars.length*.06);k++){const a=rn(stars.length),near=stars.filter(s=>s.id!==a&&!stars[a].neighbors.includes(s.id)&&Math.hypot(s.x-stars[a].x,s.y-stars[a].y)<240);if(near.length)link(stars,a,near[rn(near.length)].id)}
};
const hops=(stars:Star[],from:number,max=6)=>{const d=new Map<number,number>([[from,0]]),q=[from];while(q.length){const x=q.shift()!,dx=d.get(x)!;if(dx>=max)continue;for(const n of stars[x].neighbors)if(!d.has(n)){d.set(n,dx+1);q.push(n)}}return d};
const pickStarts=(stars:Star[],n:number,mode:StartMode)=>{const chosen:number[]=[];for(let k=0;k<n;k++){const minHop=mode==="balanced"?4:mode==="clustered"?2:1;const candidates=stars.filter(s=>s.neighbors.length>=2&&!chosen.includes(s.id)&&chosen.every(id=>(hops(stars,id,5).get(s.id)??99)>=minHop));const pool=candidates.length?candidates:stars.filter(s=>!chosen.includes(s.id));pool.sort((a,b)=>(b.neighbors.length+b.richness+(b.habitable?5:0))-(a.neighbors.length+a.richness+(a.habitable?5:0)));const top=mode==="random"?pool:pool.slice(0,Math.min(30,pool.length));chosen.push((top[rn(top.length)]??pool[0]).id)}return chosen};
const guaranteeStart=(stars:Star[],home:number,count:0|1|2)=>{const dist=hops(stars,home,3);const near=[...dist.entries()].filter(([id,d])=>id!==home&&d>=1&&d<=2).map(([id])=>stars[id]).sort((a,b)=>b.richness-a.richness);for(let i=0;i<Math.min(count,near.length);i++){near[i].habitable=true;near[i].richness=Math.max(3,near[i].richness)}const resources=near.slice(count,count+3);if(resources[0])resources[0].deposit={kind:"minerals",amount:Math.max(3,resources[0].deposit.amount)};if(resources[1])resources[1].deposit={kind:"energy",amount:Math.max(3,resources[1].deposit.amount)};if(resources[2])resources[2].deposit={kind:"science",amount:Math.max(2,resources[2].deposit.amount)}};
