const seedConstellations=(stars:Star[],gateways:Frequency)=>{const candidates=stars.filter(s=>s.owner===null);const total=Math.max(4,Math.floor(stars.length/180));for(let k=0;k<total;k++){const core=candidates[rn(candidates.length)];if(!core)continue;const gateway=k<Math.ceil(total*freq(gateways,.15,.3,.55));core.special=gateway?"Dormant Gateway":k%3===0?"Shattered Ring Fragment":k%3===1?"Void Fauna Nest":"Precursor Monument";core.richness=5;core.deposit={kind:k%2?"science":"alloys",amount:6+rn(4)};for(const n of core.neighbors.slice(0,2)){stars[n].richness=Math.max(4,stars[n].richness);if(Math.random()<.5)stars[n].anomaly=ANOMALIES[rn(ANOMALIES.length)]}}};
const seedRegions=(stars:Star[])=>{const nebulaSeeds=stars.filter(s=>s.terrain==="nebula").slice(0,Math.max(3,Math.floor(stars.length/220)));for(const core of nebulaSeeds){core.name="Veil "+core.name;for(const n of core.neighbors.slice(0,3))stars[n].terrain="nebula"}const edge=stars.filter(s=>Math.hypot(s.x-800,(s.y-600)*1.2)>560);for(const s of edge)if(Math.random()<.04){s.special="Abandoned System";s.richness=Math.max(4,s.richness);s.anomaly=s.anomaly??ANOMALIES[rn(ANOMALIES.length)]}};
const seedNamedRegions=(stars:Star[])=>{const names=["Aurelian Veil","Morrow Expanse","Nadir Drift","Cinder Reach","Glasswater Nebula","Orison Cloud","Vesper Shroud","Halcyon Rift"];const seeds=stars.filter(s=>s.terrain==="nebula").slice(0,Math.min(names.length,Math.max(3,Math.floor(stars.length/180))));seeds.forEach((seed,i)=>{const region=names[i];seed.region=region;seed.terrain="nebula";const q:[[number,number]]=[[seed.id,0]],seen=new Set<number>([seed.id]);while(q.length){const [id,d]=q.shift()!;stars[id].region=region;stars[id].terrain="nebula";if(d<2)for(const n of stars[id].neighbors)if(!seen.has(n)&&Math.random()<.72){seen.add(n);q.push([n,d+1])}}})};
const seedWormholes=(stars:Star[],rate:Frequency)=>{const pairs=Math.max(1,Math.floor(stars.length*freq(rate,.0015,.003,.006)));const free=stars.filter(s=>s.wormhole===null&&s.owner===null);for(let i=0;i<pairs&&free.length>1;i++){const a=free.splice(rn(free.length),1)[0];let candidates=free.filter(b=>Math.hypot(a.x-b.x,a.y-b.y)>650);if(!candidates.length)candidates=free;const b=candidates[rn(candidates.length)];if(!b)continue;free.splice(free.indexOf(b),1);a.wormhole=b.id;b.wormhole=a.id;a.special="Dormant Wormhole";b.special="Dormant Wormhole"}};
